المعيار:
ضرورة استيفاء جميع خطوات مصادقة المتعامل، بما في ذلك تسجيل الدخول وإعادة تعيين كلمة المرور وإدخال رمز التحقق، لمعايير إمكانية الوصول WCAG 2.2 AA، وأن توفر رسائل خطأ واضحة، وتتيح وقتًا كافيًا للإتمام الخطوات وتعيد المتعامل إلى الخدمة الأصلية بعد المصادقة الناجحة.

المتطلبات:
  1. استيفاء معايير WCAG 2.2 AA لجميع خطوات المصادقة
  2. إظهار رسائل خطأ واضحة
  3. إتاحة وقت كافٍ لإتمام الخطوات وإعادة المتعامل للخدمة الأصلية

معايير الرصد:
  1. اختبار إمكانية الوصول لواجهات المصادقة
  2. مراجعة رسائل الخطأ للتأكد من وضوحها
  3. اختبار تجربة المستخدم الكاملة

