المعيار:
صياغة محتوى الصفحة بأسلوب مختصر مع التركيز على إنجاز المهام، وذلك باستخدام لغة واضحة والإظهار التدريجي للمحتوى لتقليل التشتت. فيما يجب ألا تعيق النصوص غير الضرورية أو الوسائط الزخرفية أو الروابط الثانوية سير العمل الأساسي، وأن تضمن وضع الإجراءات المهمة للخدمة في مكان بارز.

المتطلبات:
  1. صياغة المحتوى بأسلوب مختصر مع التركيز على إنجاز المهام، باستخدام لغة واضحة وإظهار تدريجي للمحتوى
  2. ألا تعيق النصوص غير الضرورية أو الوسائط الزخرفية أو الروابط الثانوية سير العمل الأساسي
  3. وضع الإجراءات المهمة في موضع بارز

