استخدام البيانات المتاحة في السجلات الحكومية الموثقة وربط الأنظمة ذات العلاقة لتعبئة الحقول تلقائيًا، بما يضمن تطبيق مبدأ طلب البيانات مرة واحدة وعدم إعادة طلب البيانات من المتعامل.

المتطلبات:
  1. ملء الخانات بشكل تلقائي بالبيانات المعتمدة
  2. الربط مع السجلات الرقمية المعتمدة

معايير الرصد:
  1. نسبة الخانات المحدثة مسبقًا من مصادر معتمدة
  2. وجود مؤشر واضح لمصدر البيانات (مثال: “من ملفك الشخصي” أو “من الهوية الرقمية”)

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
