المعيار:
توثيق خطوات كل خدمة بشكل واضح، وإلغاء أي طلبات غير ضرورية لبيانات أو مستندات تتوفر عبر الأنظمة الحكومية، وقبول جميع المستندات المطلوبة بصيغ رقمية قابلة للمعالجة الآلية، بما يمنع التكرار أو إعادة الإدخال أو النسخ اليدوي.

المتطلبات:
  1. توثيق جميع خطوات الخدمة
  2. إلغاء طلبات البيانات/المستندات المتوفرة عبر الأنظمة الحكومية
  3. قبول المستندات بصيغ رقمية قابلة للمعالجة الآلية

معايير الرصد:
  1. وجود توثيق شامل ومحّدث لكل خدمة
  2. مراجعة دورية لإزالة الطلبات المكررة
  3. نسبة المستندات المقبولة بتنسيقات رقمية قابلة للمعالجة

