المعيار:
توفير تفاصيل الرسوم المستحقة، مع إظهار القيمة الإجمالية قبل تأكيد الدفع، ودمج جميع إجراءات الدفع ضمن خطوة واحدة، بما يمنع تجزئة عملية الدفع أو تكرار طلبها خلال رحلة المتعامل الواحدة.

المتطلبات:
  1. عرض تفصيلي للرسوم مع عرض الإجمالي النهائي قبل التأكيد
  2. دمج جميع إجراءات الدفع في خطوة واحدة

معايير الرصد:
  1. وجود تفاصيل كاملة للرسوم + عرض الإجمالي قبل التأكيد
  2. عدد خطوات الدفع في رحلة المتعامل (يجب ألا يتجاوز 1)

