المعيار:
إتاحة خدمات الدعم المباشر، مثل المحادثة الفورية أو إعادة الاتصال، ضمن رحلة المتعامل نفسها، دون إعادة توجيه المتعامل إلى قناة أخرى.

المتطلبات:
  1. إتاحة الدعم المباشر (المحادثة الفورية/إعادة اتصال) ضمن رحلة المتعامل
  2. تفادي إعادة توجيه المتعامل إلى قناة خارجية

معايير الرصد:
  1. وجود خيارات الدعم المباشر في جميع صفحات الخدمة
  2. اختبار استمرارية الرحلة عند طلب الدعم

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
