مستوى الأثر: عالي

المعيار:
معالجة جميع شكاوى وملاحظات المتعاملين ضمن نفس قناة التواصل (الموقع الإلكتروني، التطبيق الذكي، مراكز الخدمة الحضورية، مراكز الاتصال)، أو تصعيدها داخليًا دون تحويل المتعامل إلى جهات خارجية، واستخدام نفس رقم الحالة.

المتطلبات:
  1. معالجة الشكاوى والملاحظات ضمن نفس القناة أو التصعيد الداخلي
  2. عدم تحويل المتعامل إلى جهات خارجية
  3. ربط التصعيد برقم الحالة

معايير الرصد:
  1. نسبة الحالات المحلولة في نفس القناة أو المصّعدة داخليًا
  2. نسبة التحويلات الخارجية
  3. التحقق من استمرار ربط الحالة بعملية التصعيد

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
