مستوى الأثر: عالي

المعيار:
تقديم الدعم المباشر باللغة المفضلة للمتعامل حسب الملف الشخصي، مع إمكانية تبديل اللغة عند الطلب دون الحاجة إلى إعادة الخطوات.

المتطلبات:
  1. تقديم الدعم باللغة المفضلة للمتعامل حسب الملف الشخصي
  2. إمكانية تبديل اللغة دون الحاجة إلى إعادة الخطوات

معايير الرصد:
  1. نسبة تطابق لغة الدعم مع اللغة المفضلة
  2. اختبار تبديل اللغة واستمرار الجلسة

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
