[IO.File]::WriteAllText((Join-Path $Root "المحور 1 - تجربة أبسط.. أسهل.. أسرع\1.7 - الدعم الرقمي الفوري ضمن\1.7.5 - توفير دعم مباشر وفوري\المطلوب.txt"), "الكود 1.7.5  |  المحور 1: تجربة أبسط.. أسهل.. أسرع  |  المحور الفرعي 1.7: الدعم الرقمي الفوري ضمن قناة الخدمة
مستوى الأثر: عالي

المعيار:
توفير دعم مباشر وفوري للمتعاملين خلال تعبئة النماذج ورفع المستندات لمعالجة أي تحديات تشغيلية تعيق استكمال الإجراءات.

المتطلبات:
  1. تقديم المساعدة في تعبئة النماذج ورفع المستندات ومعالجة التحديات
  2. تمكين المتعامل من متابعة الخطوات بعد الدعم

معايير الرصد:
  1. تغطية الدعم لكافة مراحل تجربة المتعامل
  2. نسبة الحالات التي تم حلها وتمكين المتعامل من المتابعة

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
