مستوى الأثر: عالي

المعيار:
ضمان حصول جميع حالات الدعم المباشر على رقم مرجعي موّحد، ومعالجتها وفقًا لمؤشرات الأداء المعتمدة (مثل: عاجل: 24 ساعة، عادي: 5 أيام، معقد: 15 يومًا)، وتزويد المتعاملين بتحديثات استباقية حتى إغلاق الحالة.

المتطلبات:
  1. إصدار رقم مرجعي موّحد لكل حالة دعم
  2. المعالجة وفقًا لمؤشرات الأداء المعتمدة
  3. تزويد المتعاملين بتحديثات استباقية حتى إغلاق الحالة

معايير الرصد:
  1. نسبة الحالات التي حصلت على رقم مرجعي
  2. نسبة الحالات المحلولة ضمن المدة المحددة حسب النوع
  3. عدد التحديثات المُرسلة لكل حالة + توقيتها

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
