مستوى الأثر: عالي

المعيار:
في حال عجز المحادثة الفورية عن تقديم رد مناسب، تُصّعد الحالة تلقائيًا إلى موظف مختص مع الاحتفاظ بسياق المحادثة كاملاً دون الحاجة إلى إعادة الشرح من قبل المتعامل.

المتطلبات:
  1. تصعيد الحالة تلقائيًا إلى موظف مختص مع الاحتفاظ بسياق المحادثة

معايير الرصد:
  1. التحقق من التصعيد التلقائي واستمرارية السياق عبر المتسوق السري

