مستوى الأثر: عالي

المعيار:
ضمان عمل الخدمات بكفاءة على النطاق الترددي المنخفض وسرعات الاتصال البطيئة، من خلال ضغط الوسائط وتقليل النصوص البرمجية الثقيلة، لتمكين المتعاملين ذوي الاتصال البطيء من إتمام الخطوات او الخدمة.

المتطلبات:
  1. ضغط الوسائط لتحسين الأداء على الاتصال البطيء
  2. تقليل النصوص البرمجية الثقيلة
  3. إمكانية إتمام الخدمة على اتصال بطيء

معايير الرصد:
  1. حجم ملفات الوسائط المضغوطة
  2. حجم ملفات + وقت التحميل على سرعات منخفضة
  3. اختبار الأداء على سرعات منخفضة

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
