مستوى الأثر: عالي

المعيار:
تحسين صفحات الخدمة الرئيسية لضمان تحميل سريع عبر جميع الأجهزة، مع الامتثال التام لنظام تصميم المواقع الإلكترونية (DLS) لدولة الإمارات والمعايير العالمية لإمكانية الوصول WCAG 2.2 AA.

المتطلبات:
  1. تحسين صفحات الخدمة الرئيسية لضمان التحميل السريع
  2. الامتثال لنظام تصميم المواقع الإلكترونية (DLS)
  3. الامتثال لمعايير WCAG 2.2 AA

معايير الرصد:
  1. وقت التحميل عبر الأجهزة المختلفة
  2. مراجعة الامتثال لمعايير DLS
  3. اختبار إمكانية الوصول وفقًا ل WCAG 2.2 AA

