مستوى الأثر: متوسط

المعيار:
عرض جميع النماذج بتصميم سلس، يدعم لوحات مفاتيح الأجهزة الذكية حسب أنواع المدخلات، مع إتاحة استكمال تعبئة النموذج دون الحاجة إلى تمرير أفقي.

المتطلبات:
  1. عرض النماذج بتصميم سلس عبر جميع الأجهزة
  2. دعم لوحات مفاتيح الأجهزة الذكية المناسبة لأنواع المدخلات
  3. عدم الحاجة للتمرير الأفقي

معايير الرصد:
  1. اختبار التجاوب على أحجام شاشات مختلفة
  2. نسبة الحقول التي تفتح لوحة المفاتيح الصحيحة (رقمية/بريد/إلخ)
  3. اختبار عدم وجود تمرير أفقي على الأجهزة المحمولة

