مستوى الأثر: عالي

المعيار:
توافق الخدمات مع المتصفحات الأكثر استخدامًا في الإمارات، عبر الأجهزة المحمولة ونوافذ الخدمة الذاتية وأجهزة الحاسوب.

المتطلبات:
  1. التوافق مع المتصفحات الأكثر استخدامًا في دولة الإمارات
  2. التوافق عبر الأجهزة المختلفة (محمول/مكتبي)

معايير الرصد:
  1. اختبار التوافق مع أهم المتصفحات (Chrome, Safari, Edge, Firefox)
  2. اختبار الأداء والعرض على جميع أنواع الأجهزة

