المعيار:
قبول الشكاوى وطلبات الدعم عبر جميع قنوات الخدمة (الموقع الإلكتروني، التطبيق الذكي، مراكز الخدمة الحضورية، مراكز الاتصال)، مع ضمان معالجتها بشكلٍ متساوٍ. فيما يلتزم مزّودو الخدمة بنشر أرقام مراكز الاتصال وساعات العمل وخيارات التواصل البديلة (مثل المحادثة الفورية والبريد الإلكتروني) بوضوح على مواقعهم الإلكترونية، واختبار سهولة الوصول لهذه القنوات بشكل دوري ومعالجة أية تحديات فورًا.

المتطلبات:
  1. قبول الشكاوى عبر جميع قنوات الخدمة
  2. معالجة متساوية للشكاوى عبر جميع القنوات
  3. نشر معلومات التواصل بوضوح على الموقع الإلكتروني

معايير الرصد:
  1. وجود آليات قبول عبر جميع قنوات الخدمة
  2. مقارنة جودة ووقت المعالجة عبر القنوات
  3. وجود جميع معلومات التواصل واضحة على الموقع

