المعيار:
توفير استمارة واحدة متعددة الخدمات، حيثما يسمح الإطار القانوني، لجمع البيانات المشتركة مرة واحدة فقط، وتوجيهها تلقائيًا إلى كل خدمة من الخدمات المشاركة في الباقة.

المتطلبات:
  1. توفير استمارة واحدة متعددة الخدمات لكل باقة حدث حياتي
  2. جمع البيانات المشتركة مرة واحدة فقط دون تكرار
  3. التوجيه التلقائي للبيانات إلى كل خدمة مشاركة

معايير الرصد:
  1. وجود استمارة موحدة لكل باقة تجمع البيانات لجميع الخدمات المشاركة
  2. عدم طلب نفس البيانات من المتعامل أكثر من مرة ضمن الباقة
  3. اختبار تدفق البيانات التلقائي من الاستمارة إلى جميع الخدمات المشاركة

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
