المعيار:
مراجعة كل باقة حدث حياتي بشكل سنوي لإضافة أو إيقاف أية خدمات حسب الحاجة، وتحديث الخطوات والمستندات المطلوبة بما يعكس التغييرات في السياسات المعتمدة

المتطلبات:
  1. إجراء مراجعة سنوية لكل باقة حدث حياتي
  2. إضافة أو إيقاف الخدمات المشمولة بناءً على المراجعة
  3. تحديث الخطوات والمستندات لتعكس تغييرات السياسات

معايير الرصد:
  1. توثيق المراجعة السنوية لكل باقة (مرة واحدة على الأقل كل 12 شهرًا)
  2. توثيق أي تغييرات في الخدمات المشمولة في الباقة
  3. توثيق التحديثات على الخطوات والمستندات بعد كل تغيير في السياسات

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
