المعيار:
رصد النظام لأهلية المتعامل للخدمات المرتبطة بالحدث الحياتي، وذلك بناءً على بيانات المتعامل، وإرسال إشعار استباقي بالباقة ذات الصلة يتضمن رابطًا للبدء بالخدمة وقائمة بالمستندات والرسوم المطلوبة.

المتطلبات:
  1. رصد أهلية المتعامل للحدث الحياتي بناءً على البيانات المتوفرة
  2. إرسال إشعار استباقي للمتعامل المؤهل
  3. تضمين رابط البدء وقائمة المستندات والرسوم في الإشعار

معايير الرصد:
  1. وجود آلية تقنية آلية تكتشف الأهلية من البيانات المقدمة من المتعامل
  2. نسبة المتعاملين المؤهلين الذين تم إشعارهم استباقيًا
  3. اشتمال كل إشعار على: رابط مباشر للبدء، قائمة كاملة بالمستندات، تفاصيل الرسوم

