المعيار:
الحصول على موافقة صريحة من المتعاملين، قبل تطبيق أي عملية تخصيص، تُحدد بوضوح فئات البيانات التي سيتم استخدامها والغرض من هذا الاستخدام.

المتطلبات:
  1. الحصول على موافقة صريحة من المتعامل قبل تطبيق أي تخصيص
  2. تحديد فئات البيانات المستخدمة في نص الموافقة
  3. توضيح الغرض من استخدام البيانات في نص الموافقة

معايير الرصد:
  1. عدم تفعيل أي تخصيص قبل تسجيل موافقة المتعامل
  2. مراجعة نص الموافقة للتأكد من ذكر جميع فئات البيانات
  3. مراجعة نص الموافقة للتأكد من وضوح الغرض

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
$p = Join-Path $Root "المحور 3 - أنسنة الخدمات\3.3 - إدارة موافقة المتعامل\3.3.2 - تسجيل كل موافقة مع الختم"; if (-not (Test-Path -LiteralPath $p)) { New-Item -ItemType Directory -Path $p -Force | Out-Null; $n++ }
[IO.File]::WriteAllText((Join-Path $Root "المحور 3 - أنسنة الخدمات\3.3 - إدارة موافقة المتعامل\3.3.2 - تسجيل كل موافقة مع الختم\المطلوب.txt"), "الكود 3.3.2  |  المحور 3: أنسنة الخدمات  |  المحور الفرعي 3.3: إدارة موافقة المتعامل على التخصيص
مستوى الأثر: عالي

المعيار:
تسجيل كل موافقة مع الختم الزمني الخاص بها وربطها بهوية المتعامل وحفظها في سجل تدقيق غير قابل للتعديل، مع ضمان إمكانية استخراجها لتقديمها كدليل عند الحاجة.

المتطلبات:
  1. تسجيل كل موافقة مع الختم الزمني وهوية المتعامل
  2. حفظ الموافقة في سجل تدقيق غير قابل للتعديل
  3. إمكانية استخراج سجلات الموافقة كدليل

معايير الرصد:
  1. مراجعة سجل التدقيق للتأكد من تسجيل: الختم الزمني، هوية المتعامل لكل حدث موافقة
  2. اختبار عدم إمكانية تعديل أو حذف سجلات الموافقة
  3. اختبار استرجاع سجلات الموافقة لمتعامل محدد في أي وقت

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
$p = Join-Path $Root "المحور 3 - أنسنة الخدمات\3.3 - إدارة موافقة المتعامل\3.3.3 - يحق للمتعاملين إلغاء موافقتهم"; if (-not (Test-Path -LiteralPath $p)) { New-Item -ItemType Directory -Path $p -Force | Out-Null; $n++ }
[IO.File]::WriteAllText((Join-Path $Root "المحور 3 - أنسنة الخدمات\3.3 - إدارة موافقة المتعامل\3.3.3 - يحق للمتعاملين إلغاء موافقتهم\المطلوب.txt"), "الكود 3.3.3  |  المحور 3: أنسنة الخدمات  |  المحور الفرعي 3.3: إدارة موافقة المتعامل على التخصيص
مستوى الأثر: متوسط

المعيار:
يحق للمتعاملين إلغاء موافقتهم على التخصيص في أي وقت من خلال تعديل إعدادات الحساب، على أن يسري مفعول الإلغاء فورًا على جميع عمليات التخصيص.

المتطلبات:
  1. إتاحة خيار إلغاء الموافقة من خلال إعدادات الحساب
  2. السريان الفوري لإلغاء الموافقة على جميع عمليات التخصيص

معايير الرصد:
  1. وجود خيار واضح وسهل الوصول لإلغاء الموافقة في إعدادات الحساب
  2. اختبار إيقاف جميع عمليات التخصيص فورًا بعد الإلغاء

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
$p = Join-Path $Root "المحور 3 - أنسنة الخدمات\3.3 - إدارة موافقة المتعامل\3.3.4 - ضمان تحقق النظام من موافقة"; if (-not (Test-Path -LiteralPath $p)) { New-Item -ItemType Directory -Path $p -Force | Out-Null; $n++ }
[IO.File]::WriteAllText((Join-Path $Root "المحور 3 - أنسنة الخدمات\3.3 - إدارة موافقة المتعامل\3.3.4 - ضمان تحقق النظام من موافقة\المطلوب.txt"), "الكود 3.3.4  |  المحور 3: أنسنة الخدمات  |  المحور الفرعي 3.3: إدارة موافقة المتعامل على التخصيص
مستوى الأثر: متوسط

المعيار:
ضمان تحقق النظام من موافقة المتعامل على التخصيص أثناء تشغيل الخدمة. وفي حال عدم منح المتعامل الموافقة أو عند سحب الموافقة، يجب على النظام التوقف عن استخدام البيانات الشخصية لأغراض التخصيص، وعرض مسار الخدمة غير المخصص بدلاً من ذلك.

المتطلبات:
  1. التحقق من حالة موافقة المستخدم على التخصيص أثناء تشغيل الخدمة
  2. عرض مسار الخدمة غير المخصص عند عدم وجود موافقة فّعالة

معايير الرصد:
  1. اختبار استعلام النظام عن حالة الموافقة قبل تطبيق التخصيص
  2. اختبار عرض المسار غير المخصص لمتعامل بدون موافقة أو بموافقة مسحوبة

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
$p = Join-Path $Root "المحور 3 - أنسنة الخدمات\3.3 - إدارة موافقة المتعامل\3.3.5 - استخدام لغة واضحة وبسيطة عند"; if (-not (Test-Path -LiteralPath $p)) { New-Item -ItemType Directory -Path $p -Force | Out-Null; $n++ }
[IO.File]::WriteAllText((Join-Path $Root "المحور 3 - أنسنة الخدمات\3.3 - إدارة موافقة المتعامل\3.3.5 - استخدام لغة واضحة وبسيطة عند\المطلوب.txt"), "الكود 3.3.5  |  المحور 3: أنسنة الخدمات  |  المحور الفرعي 3.3: إدارة موافقة المتعامل على التخصيص
مستوى الأثر: متوسط

المعيار:
استخدام لغة واضحة وبسيطة، عند عرض طلبات الموافقة، وتحديد البيانات التي سيتم استخدامها والغرض من الاستخدام وكيفية سحب الموافقة، وذلك دون تفعيل أي خانات اختيار مسبقًا.

المتطلبات:
  1. استخدام لغة واضحة وبسيطة عند عرض طلبات الموافقة
  2. تحديد البيانات والغرض وكيفية السحب في طلب الموافقة
  3. عدم تفعيل أي خانات اختيار مسبقًا

معايير الرصد:
  1. مراجعة نصوص الموافقة للتأكد من وضوحها وبساطتها
  2. اشتمال كل طلب موافقة على: البيانات المحددة، الغرض، كيفية السحب
  3. مراجعة واجهة طلب الموافقة للتأكد من عدم وجود خانات ُمفّعلة افتراضيًا

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
$p = Join-Path $Root "المحور 3 - أنسنة الخدمات\3.3 - إدارة موافقة المتعامل\3.3.6 - عند تغيير شروط الموافقة لا بد"; if (-not (Test-Path -LiteralPath $p)) { New-Item -ItemType Directory -Path $p -Force | Out-Null; $n++ }
[IO.File]::WriteAllText((Join-Path $Root "المحور 3 - أنسنة الخدمات\3.3 - إدارة موافقة المتعامل\3.3.6 - عند تغيير شروط الموافقة لا بد\المطلوب.txt"), "الكود 3.3.6  |  المحور 3: أنسنة الخدمات  |  المحور الفرعي 3.3: إدارة موافقة المتعامل على التخصيص
مستوى الأثر: عالي

المعيار:
عند تغيير شروط الموافقة، لا بد من إخطار المتعاملين بلغة واضحة ومفهومة ومطالبتهم بإعادة تأكيد موافقتهم لضمان فهمهم التام للتبعات المترتبة على الموافقة، قبل بدء أية معالجة جديدة للبيانات.

المتطلبات:
  1. إخطار المتعاملين بلغة واضحة ومفهومة عند تغيير شروط الموافقة
  2. مطالبة المتعاملين بإعادة تأكيد موافقتهم قبل تطبيق الشروط الجديدة
  3. ضمان فهم المتعاملين للتبعات قبل بدء المعالجة الجديدة

معايير الرصد:
  1. مراجعة نص الإخطار للتأكد من وضوحه وسهولة فهمه
  2. عدم تطبيق الشروط الجديدة إلا بعد الحصول على موافقة جديدة
  3. توضيح التبعات بشكل صريح في نص طلب إعادة التأكيد

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
$p = Join-Path $Root "المحور 3 - أنسنة الخدمات\3.4 - ملف المتعامل الموحد"; if (-not (Test-Path -LiteralPath $p)) { New-Item -ItemType Directory -Path $p -Force | Out-Null; $n++ }
$p = Join-Path $Root "المحور 3 - أنسنة الخدمات\3.4 - ملف المتعامل الموحد\3.4.1 - توفير سجل موحد وشامل لكل"; if (-not (Test-Path -LiteralPath $p)) { New-Item -ItemType Directory -Path $p -Force | Out-Null; $n++ }
[IO.File]::WriteAllText((Join-Path $Root "المحور 3 - أنسنة الخدمات\3.4 - ملف المتعامل الموحد\3.4.1 - توفير سجل موحد وشامل لكل\المطلوب.txt"), "الكود 3.4.1  |  المحور 3: أنسنة الخدمات  |  المحور الفرعي 3.4: ملف المتعامل الموحد
مستوى الأثر: عالي

المعيار:
توفير سجل موحد وشامل لكل متعامل يعرض المعّرفات الرئيسية وتفاصيل الاتصال والحالات والمدفوعات وسجل الاتصالات عبر جميع الخدمات.

المتطلبات:
  1. توفير سجل موحد شامل لكل متعامل
  2. عرض جميع العناصر الأساسية في السجل الموحد
  3. تغطية جميع الخدمات في السجل الموحد

معايير الرصد:
  1. وجود سجل واحد يجمع بيانات المتعامل من جميع الخدمات
  2. اشتمال السجل على: المعّرفات الرئيسية، تفاصيل الاتصال، الحالات، المدفوعات، سجل الاتصالات
  3. اختبار عرض البيانات من جميع الخدمات التي تعامل معها المتعامل

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
$p = Join-Path $Root "المحور 3 - أنسنة الخدمات\3.4 - ملف المتعامل الموحد\3.4.2 - ضمان أن تنعكس أية تغييرات على"; if (-not (Test-Path -LiteralPath $p)) { New-Item -ItemType Directory -Path $p -Force | Out-Null; $n++ }
[IO.File]::WriteAllText((Join-Path $Root "المحور 3 - أنسنة الخدمات\3.4 - ملف المتعامل الموحد\3.4.2 - ضمان أن تنعكس أية تغييرات على\المطلوب.txt"), "الكود 3.4.2  |  المحور 3: أنسنة الخدمات  |  المحور الفرعي 3.4: ملف المتعامل الموحد
مستوى الأثر: منخفض

المعيار:
ضمان أن تنعكس أية تغييرات على سمات المتعامل في السجل الموحد خلال دقيقة واحدة كحد أقصى، بحيث تعرض جميع القنوات نفس المعلومات المحّدثة.

المتطلبات:
  1. انعكاس التغييرات على السجل الموحد خلال دقيقة واحدة كحد أقصى
  2. عرض نفس المعلومات المحّدثة عبر جميع القنوات

معايير الرصد:
  1. قياس الوقت بين إجراء التغيير وظهوره في السجل الموحد
  2. اختبار عرض البيانات المحّدثة بشكل متطابق عبر القنوات المختلفة

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
$p = Join-Path $Root "المحور 3 - أنسنة الخدمات\3.4 - ملف المتعامل الموحد\3.4.3 - عندما يحتوي السجل الموحد على"; if (-not (Test-Path -LiteralPath $p)) { New-Item -ItemType Directory -Path $p -Force | Out-Null; $n++ }
[IO.File]::WriteAllText((Join-Path $Root "المحور 3 - أنسنة الخدمات\3.4 - ملف المتعامل الموحد\3.4.3 - عندما يحتوي السجل الموحد على\المطلوب.txt"), "الكود 3.4.3  |  المحور 3: أنسنة الخدمات  |  المحور الفرعي 3.4: ملف المتعامل الموحد
مستوى الأثر: متوسط

المعيار:
عندما يحتوي السجل الموحد على سمة موثّقة، يتم تعبئة الحقل المقابل لهذه السمة في النماذج مسبقًا، والاكتفاء بطلب التأكيد أو التصحيح من المتعامل.

المتطلبات:
  1. التعبئة المسبقة للحقول التي تحتوي على سمات موثّقة في السجل الموحد
  2. الاكتفاء بطلب التأكيد أو التصحيح من المتعامل

معايير الرصد:
  1. اختبار تعبئة النماذج تلقائيًا من البيانات الموثّقة
  2. عدم مطالبة المتعامل بإعادة إدخال البيانات الموثّقة المتوفرة

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
$p = Join-Path $Root "المحور 3 - أنسنة الخدمات\3.4 - ملف المتعامل الموحد\3.4.4 - التأكد من أن جميع السمات في"; if (-not (Test-Path -LiteralPath $p)) { New-Item -ItemType Directory -Path $p -Force | Out-Null; $n++ }
[IO.File]::WriteAllText((Join-Path $Root "المحور 3 - أنسنة الخدمات\3.4 - ملف المتعامل الموحد\3.4.4 - التأكد من أن جميع السمات في\المطلوب.txt"), "الكود 3.4.4  |  المحور 3: أنسنة الخدمات  |  المحور الفرعي 3.4: ملف المتعامل الموحد
مستوى الأثر: متوسط

المعيار:
التأكد من أن جميع السمات في السجل الموحد تتضمن حالة التحقق منها والختم الزمني لآخر تحديث، بحيث يتم استمدادها حصريًا من أنظمة السجل الموثوقة.

المتطلبات:
  1. إرفاق حالة التحقق والختم الزمني لكل سمة في السجل الموحد
  2. الاستمداد الحصري من أنظمة السجل الموثوقة

معايير الرصد:
  1. مراجعة بنية البيانات للتأكد من وجود حقول: حالة التحقق، الختم الزمني لكل سمة
  2. توثيق مصادر البيانات والتأكد من موثوقيتها واعتمادها

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
$p = Join-Path $Root "المحور 3 - أنسنة الخدمات\3.4 - ملف المتعامل الموحد\3.4.5 - تمكين الموظفين المخّولين من"; if (-not (Test-Path -LiteralPath $p)) { New-Item -ItemType Directory -Path $p -Force | Out-Null; $n++ }
[IO.File]::WriteAllText((Join-Path $Root "المحور 3 - أنسنة الخدمات\3.4 - ملف المتعامل الموحد\3.4.5 - تمكين الموظفين المخّولين من\المطلوب.txt"), "الكود 3.4.5  |  المحور 3: أنسنة الخدمات  |  المحور الفرعي 3.4: ملف المتعامل الموحد
مستوى الأثر: عالي

المعيار:
تمكين الموظفين المخّولين من الاطلاع على السجل الموحد للمتعامل ضمن حدود صلاحيات أدوارهم الوظيفية دون الحاجة لاستخدام تطبيقات منفصلة، سواء داخل الجهة أو من خلال صلاحيات وصول معتمدة للجهات المشاركة في نفس باقة الخدمة، وذلك عندما تقتضي الحاجة.

المتطلبات:
  1. إتاحة الاطلاع على السجل الموحد للموظفين المخّولين ضمن صلاحياتهم
  2. عدم الحاجة لاستخدام تطبيقات منفصلة
  3. إتاحة الوصول المعتمد للجهات المشاركة في نفس باقة الخدمة

معايير الرصد:
  1. اختبار الوصول للموظفين وفق صلاحيات أدوارهم
  2. وجود واجهة موحدة للاطلاع على السجل الموحد
  3. اختبار وصول الجهات المشاركة وفق الصلاحيات المعتمدة

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
$p = Join-Path $Root "المحور 3 - أنسنة الخدمات\3.4 - ملف المتعامل الموحد\3.4.6 - تمكين المتعاملين من الاطلاع"; if (-not (Test-Path -LiteralPath $p)) { New-Item -ItemType Directory -Path $p -Force | Out-Null; $n++ }
[IO.File]::WriteAllText((Join-Path $Root "المحور 3 - أنسنة الخدمات\3.4 - ملف المتعامل الموحد\3.4.6 - تمكين المتعاملين من الاطلاع\المطلوب.txt"), "الكود 3.4.6  |  المحور 3: أنسنة الخدمات  |  المحور الفرعي 3.4: ملف المتعامل الموحد
مستوى الأثر: متوسط

المعيار:
تمكين المتعاملين من الاطلاع بشكل آمن على البيانات الرئيسية المخزنة عنهم من خلال واجهة الخدمة الذاتية، ومنحهم إمكانية طلب تصحيح هذه البيانات والموافقة الصريحة على مشاركتها مع جهات أخرى أو رفض ذلك.

المتطلبات:
  1. إتاحة الاطلاع الآمن على البيانات الرئيسية من خلال واجهة الخدمة الذاتية
  2. توفير إمكانية طلب تصحيح البيانات
  3. توفير إمكانية الموافقة الصريحة على المشاركة أو رفضها

معايير الرصد:
  1. وجود واجهة آمنة تتيح للمتعامل الاطلاع على بياناته
