المعيار:
ضمان دعم طلبات الخدمات الإلكترونية خاصية الحفظ التلقائي لتقدم المتعامل، وتمكين المتعامل من استئناف الخدمة من نفس الخطوة مع الاحتفاظ بجميع البيانات المدخلة.

المتطلبات:
  1. الحفظ التلقائي لتقدم المتعامل في الطلب الخاص بالخدمة
  2. إتاحة استئناف الطلب من الخطوة ذاتها التي توقف عندها المتعامل
  3. الاحتفاظ بجميع البيانات المدخلة دون فقدان أية منها

معايير الرصد:
  1. اختبار حفظ البيانات تلقائيًا أثناء التنقل بين الخطوات
  2. اختبار العودة للطلب والتأكد من استئنافه من آخر خطوة
  3. التحقق من عدم فقدان أي بيانات بعد الاستئناف

