المعيار:
ضمان تلقي المتعامل رسالة تأكيد، عند اكتمال أي إجراء حاسم، تتضمن الرقم المرجعي للمعاملة والخطوة التالية إن ُوجدت.

المتطلبات:
  1. إرسال رسالة تأكيد فورًا عند اكتمال أي إجراء حاسم
  2. تضمين الرقم المرجعي للمعاملة في رسالة التأكيد
  3. تضمين الخطوة التالية في رسالة التأكيد (إن ُوجدت)

معايير الرصد:
  1. اختبار إرسال رسالة التأكيد بعد كل إجراء حاسم
  2. مراجعة محتوى رسالة التأكيد للتأكد من وجود الرقم المرجعي
  3. مراجعة محتوى رسالة التأكيد للتأكد من توضيح الخطوة التالية عند الاقتضاء

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
