$p = Join-Path $Root "المحور 3 - أنسنة الخدمات\3.7 - عرض إرشادات حسب تصنيف\3.7.1 - عرض جداول الرسوم المعدل"; if (-not (Test-Path -LiteralPath $p)) { New-Item -ItemType Directory -Path $p -Force | Out-Null; $n++ }
[IO.File]::WriteAllText((Join-Path $Root "المحور 3 - أنسنة الخدمات\3.7 - عرض إرشادات حسب تصنيف\3.7.1 - عرض جداول الرسوم المعدل\المطلوب.txt"), "الكود 3.7.1  |  المحور 3: أنسنة الخدمات  |  المحور الفرعي 3.7: عرض إرشادات حسب تصنيف المتعامل
مستوى الأثر: متوسط

المعيار:
عرض جداول الرسوم المعدل الصحيح حسب فئة المتعامل مع والإعفاءات إن ُوجدت.

المتطلبات:
  1. عرض المعدل الصحيح للرسوم حسب فئة المتعامل
  2. توضيح أسس احتساب الرسوم
  3. توضيح الإعفاءات (إن ُوجدت)

معايير الرصد:
  1. اختبار عرض معدلات مختلفة لمتعاملين من فئات مختلفة
  2. وجود شرح واضح لكيفية احتساب الرسوم لكل فئة
  3. عرض الإعفاءات المتاحة لكل فئة بوضوح

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
