[IO.File]::WriteAllText((Join-Path $Root "المحور 3 - أنسنة الخدمات\3.7 - عرض إرشادات حسب تصنيف\3.7.2 - عرض صفحات الإرشادات للقواعد\المطلوب.txt"), "الكود 3.7.2  |  المحور 3: أنسنة الخدمات  |  المحور الفرعي 3.7: عرض إرشادات حسب تصنيف المتعامل
مستوى الأثر: عالي

المعيار:
عرض صفحات الإرشادات للقواعد والمتطلبات والمستندات المطلوبة الخاصة بكل فئة، وذلك لتمكين المتعاملين من فهم المتطلبات بشكل كامل قبل التقديم.

المتطلبات:
  1. توضيح القواعد والمتطلبات الخاصة بكل فئة
  2. توضيح المستندات المطلوبة الخاصة بكل فئة
  3. وضوح وشمولية المتطلبات قبل التقديم

معايير الرصد:
  1. وجود معايير أهلية محددة ومفصلة لكل فئة في صفحات الإرشادات
  2. وجود قائمة كاملة بالمستندات المطلوبة لكل فئة
  3. مراجعة صفحات الإرشادات للتأكد من وضوح جميع المتطلبات

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
$p = Join-Path $Root "المحور 3 - أنسنة الخدمات\3.7 - عرض إرشادات حسب تصنيف\3.7.3 - عند تغيير القواعد والمتطلبات"; if (-not (Test-Path -LiteralPath $p)) { New-Item -ItemType Directory -Path $p -Force | Out-Null; $n++ }
[IO.File]::WriteAllText((Join-Path $Root "المحور 3 - أنسنة الخدمات\3.7 - عرض إرشادات حسب تصنيف\3.7.3 - عند تغيير القواعد والمتطلبات\المطلوب.txt"), "الكود 3.7.3  |  المحور 3: أنسنة الخدمات  |  المحور الفرعي 3.7: عرض إرشادات حسب تصنيف المتعامل
مستوى الأثر: متوسط

المعيار:
عند تغيير القواعد والمتطلبات أو الرسوم، لا بد من تحديث الإرشادات فورًا مع توضيح تاريخ سريان التغيير بشكل واضح.

المتطلبات:
  1. التحديث الفوري للإرشادات عند تغيير القواعد والمتطلبات أو الرسوم
  2. توضيح تاريخ سريان التغيير بشكل واضح

معايير الرصد:
  1. قياس الوقت بين اعتماد التغيير ونشر الإرشادات المحدثة
  2. وجود تاريخ سريان واضح في صفحات الإرشادات المحدثة

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
$p = Join-Path $Root "المحور 3 - أنسنة الخدمات\3.7 - عرض إرشادات حسب تصنيف\3.7.4 - ضمان تلقي المتعاملين الذين"; if (-not (Test-Path -LiteralPath $p)) { New-Item -ItemType Directory -Path $p -Force | Out-Null; $n++ }
