مستوى الأثر: منخفض

المعيار:
ضمان تلقي المتعاملين الذين وافقوا على تلقي الإشعارات رسالة تلخص التغيير وتتضمن رابطًا مباشرًا للإرشادات المحدثة.

المتطلبات:
  1. إرسال رسالة للمتعاملين الذين وافقوا على تلقي الإشعارات
  2. تضمين ملخص للتغيير في الرسالة
  3. تضمين رابط مباشر للإرشادات المحدثة

معايير الرصد:
  1. اختبار إرسال الرسالة للمتعاملين المشتركين فقط
  2. مراجعة محتوى الرسالة للتأكد من وضوح التغيير
  3. وجود رابط فّعال يوجه للصفحة المحدثة

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
