مستوى الأثر: متوسط

المعيار:
إظهار شاشة المراجعة النهائية لعرض واضح ومفصل لجميع بنود الرسوم والمبلغ الإجمالي قبل تأكيد المتعامل.

المتطلبات:
  1. عرض جميع بنود الرسوم في شاشة المراجعة النهائية
  2. عرض المبلغ الإجمالي بوضوح
  3. عرض التفصيل قبل تأكيد المتعامل

معايير الرصد:
  1. مراجعة شاشة المراجعة النهائية للتأكد من عرض كل بند من بنود الرسوم
  2. وجود المجموع الإجمالي واضحًا ومميزًا بصريًا
  3. التأكد من أن شاشة المراجعة تسبق خطوة التأكيد النهائي

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
