[IO.File]::WriteAllText((Join-Path $Root "المحور 3 - أنسنة الخدمات\3.7 - عرض إرشادات حسب تصنيف\3.7.6 - تطوير قسم للأسئلة الشائعة لكل\المطلوب.txt"), "الكود 3.7.6  |  المحور 3: أنسنة الخدمات  |  المحور الفرعي 3.7: عرض إرشادات حسب تصنيف المتعامل
مستوى الأثر: عالي

المعيار:
تطوير قسم للأسئلة الشائعة لكل فئة، حيث يغطي القواعد والمتطلبات والرسوم والتحديات الشائعة، على أن تتم مراجعته مرة واحدة على الأقل كل سنة لضمان دقته وتحديثه.

المتطلبات:
  1. تطوير قسم للأسئلة الشائعة لكل فئة
  2. تغطية القواعد والمتطلبات والرسوم والتحديات الشائعة
  3. المراجعة الفصلية (كل سنة على الأقل)

معايير الرصد:
  1. وجود قسم مخصص للأسئلة الشائعة لكل فئة من فئات المتعاملين
  2. مراجعة محتوى الأسئلة الشائعة للتأكد من تغطية المواضيع الثلاثة
  3. توثيق المراجعة الدورية

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
