مستوى الأثر: متوسط

المعيار:
استخدام المكونات المرئية والصياغات اللغوية والوظائف الأساسية ذاتها عبر جميع القنوات (الموقع الإلكتروني، التطبيق الذكي، مراكز الخدمة الحضورية، مراكز الاتصال) لضمان الاتساق التام في التجربة.

المتطلبات:
  1. استخدام نفس المكونات المرئية عبر جميع القنوات
  2. استخدام نفس الصياغات اللغوية عبر جميع القنوات
  3. استخدام نفس الوظائف الأساسية عبر جميع القنوات

معايير الرصد:
  1. مقارنة المكونات المرئية (أزرار، نماذج، تنبيهات) عبر القنوات المختلفة
  2. مقارنة النصوص والتسميات عبر القنوات المختلفة
  3. اختبار تطابق سلوك الوظائف الأساسية عبر القنوات

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
