[IO.File]::WriteAllText((Join-Path $Root "المحور 4 - اتساق التجربة عبر مختلف\4.1 - تناسق قنوات الخدمة\4.1.2 - تمكين المتعامل من إنجاز\المطلوب.txt"), "الكود 4.1.2  |  المحور 4: اتساق التجربة عبر مختلف قنوات الخدمة  |  المحور الفرعي 4.1: تناسق قنوات الخدمة
مستوى الأثر: عالي

المعيار:
تمكين المتعامل من إنجاز الخدمة بالكامل في كل قناة من البداية حتى النهاية، بما في ذلك حالات التمكين الرقمي (مثل طلب إرشادات الخدمة عبر مراكز الاتصال أو مراكز الخدمة)، دون إلزام المتعامل بالانتقال إلى قناة أخرى.

المتطلبات:
  1. إتاحة إنجاز الخدمة بالكامل من خلال أي قناة
  2. دعم حالات التمكين الرقمي عبر القنوات غير الرقمية
  3. عدم إجبار المتعامل على الانتقال لقناة أخرى

معايير الرصد:
  1. اختبار إنجاز الخدمة كاملة من خلال كل قناة على حدة
  2. اختبار تقديم الدعم الرقمي عبر مراكز الاتصال ومراكز الخدمة
  3. التحقق من عدم وجود خطوات تتطلب الانتقال لقناة مختلفة

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
