مستوى الأثر: متوسط

المعيار:
ضمان تطابق الشعارات والألوان والخطوط والمحتوى مع معايير الهوية والأسلوب التحريري المعتمد عبر جميع القنوات والتوافق مع نظام تصميم المواقع الإلكترونية (DLS).

المتطلبات:
  1. تطابق الشعارات والألوان والخطوط والمحتوى مع معايير الهوية والأسلوب التحريري المعتمد
  2. التوافق مع نظام تصميم المواقع الإلكترونية (DLS).

معايير الرصد:
  1. مراجعة تطابق العناصر عبر القنوات المختلفة
  2. مراجعة التوافق عبر القنوات المختلفة

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
$p = Join-Path $Root "المحور 4 - اتساق التجربة عبر مختلف\4.1 - تناسق قنوات الخدمة\4.1.4 - الحفاظ على استمرارية الهوية"; if (-not (Test-Path -LiteralPath $p)) { New-Item -ItemType Directory -Path $p -Force | Out-Null; $n++ }
[IO.File]::WriteAllText((Join-Path $Root "المحور 4 - اتساق التجربة عبر مختلف\4.1 - تناسق قنوات الخدمة\4.1.4 - الحفاظ على استمرارية الهوية\المطلوب.txt"), "الكود 4.1.4  |  المحور 4: اتساق التجربة عبر مختلف قنوات الخدمة  |  المحور الفرعي 4.1: تناسق قنوات الخدمة
مستوى الأثر: عالي

المعيار:
الحفاظ على استمرارية الهوية الرقمية المعتمدة ذاتها (مثل UAE PASS) طوال رحلة المتعامل بالكامل، بما يشمل الانتقال بين الجهات الشريكة، بغض النظر عن عدد الأطراف المشاركة.

المتطلبات:
  1. استمرارية الهوية الرقمية المعتمدة طوال الرحلة
  2. الحفاظ على الهوية عند الانتقال بين الجهات الشريكة

معايير الرصد:
  1. اختبار استخدام نفس الهوية الرقمية عبر جميع نقاط الرحلة
  2. اختبار عدم طلب إعادة المصادقة عند الانتقال بين الجهات

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
