[IO.File]::WriteAllText((Join-Path $Root "المحور 4 - اتساق التجربة عبر مختلف\4.1 - تناسق قنوات الخدمة\4.1.5 - توحيد تسميات الحقول\المطلوب.txt"), "الكود 4.1.5  |  المحور 4: اتساق التجربة عبر مختلف قنوات الخدمة  |  المحور الفرعي 4.1: تناسق قنوات الخدمة
مستوى الأثر: متوسط

المعيار:
توحيد تسميات الحقول وتنسيقاتها عبر جميع القنوات لضمان عدم مطالبة المتعاملين بإدخال نفس البيانات بصيغ مختلفة.

المتطلبات:
  1. توحيد تسميات الحقول عبر جميع القنوات
  2. توحيد تنسيقات الحقول عبر جميع القنوات
  3. عدم مطالبة المتعاملين بصيغ مختلفة لنفس البيانات

معايير الرصد:
  1. مقارنة تسميات الحقول عبر القنوات المختلفة
  2. مقارنة تنسيقات الحقول عبر القنوات
