المعيار:
ضمان قيام الأنظمة بالتحقق الآلي من صحة بيانات المتعاملين عند إدخالها، بما يشمل التحقق من الصيغة والمعلومات المقبولة والتناسق المنطقي بين الحقول، وعدم السماح بحفظ البيانات قبل تصحيح جميع الأخطاء.

