المعيار:
تصحيح الأخطاء المكتشفة في بيانات النظام خلال مدة لا تتجاوز 48 ساعة من تاريخ اكتشافها، مع تسجيل عملية التصحيح في سجل تدقيق يبّين طبيعة الخطأ، وسبب التعديل، وهوية المستخدم، وتاريخ ووقت الإجراء.

المتطلبات:
