المعيار:
إجراء مراجعة سنوية شاملة لجودة البيانات، تشمل عّينة من السجلات النشطة للتحقق من دقة البيانات واكتمالها، وإعداد خطة إجراءات تصحيحية تتضمن الجداول الزمنية والمسؤوليات المحددة

المتطلبات:
  1. إجراء مراجعة سنوية لجودة البيانات على عينة من السجلات النشطة
