  2. تحديد الصلاحيات وحدود الوصول وأنواع القرارات المستقلة والقرارات التي تتطلب تدخلاً بشرًيا
  3. تحديث نطاق الذكاء الاصطناعي المساعد واعتماده عند أي تغيير جوهري ومنع تشغيله خارج النطاق المعتمد

