عند تصعيد الحالة، لا بد أن يتلقى المتعامل رسالة تؤكد التصعيد، وتوضح صاحب الحالة الجديد وموعد التحديث التالي المتوقع.

المتطلبات:
  1. إرسال رسالة تأكيد التصعيد للمتعامل
  2. تضمين المعلومات المطلوبة في الرسالة

معايير الرصد:
  1. اختبار إرسال الرسالة عند كل تصعيد
  2. مراجعة محتوى الرسالة للتأكد من وجود: تأكيد التصعيد، المالك الجديد، موعد التحديث التالي

ضع في هذا المجلد الأدلة الخاصة بهذا الكود (مستندات، لقطات شاشة، تقارير)، ثم أضف رابط المجلد في الأداة عند التقييم.", $utf8)
