المعيار:
ضمان حل الحالات المُصّعدة ضمن الإطار الزمني المحدد، ووفق مؤشرات التصعيد الموحدة (مثل: العاجلة = 24 ساعة، العادية = 5 أيام، المعقدة = 15 يوًما)، أو الاتفاق على موعد جديد مع المتعامل وتوثيق أسباب التعديل.

المتطلبات:
  1. حل الحالات ضمن الإطار الزمني المحدد في مؤشرات التصعيد الموحدة
  2. الاتفاق مع المتعامل على موعد جديد عند التأخير

معايير الرصد:
  1. قياس نسبة الحالات المحلولة ضمن الإطار المحدد
  2. توثيق الاتفاق والأسباب في سجل الحالة

